($m['metricas']['Error ponderado WAPE (%)']??'—') ?>%</p><?php if(($m['metricas']['Error ponderado WAPE (%)']??0)>=50): ?><p class="control-warning">Error histórico alto: requiere revisión humana. Un modelo vigente también puede equivocarse mucho.</p><?php endif; ?><?php if(isset($m['decision'])): ?><p><strong><?= e($m['decision']['advertencia']) ?></strong></p><?php endif; ?><a class="btn-action" href="<?= e($tipo) ?>_ia.php">Ver gráficos y comparación ↗</a></section><?php endforeach; ?></div>
